-- Table: transaction_quotation_detail
-- Source: accounting_admin_db.sql (3. Sales flow)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS transaction_quotation_detail (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    quotation_id      BIGINT NOT NULL REFERENCES transaction_quotation(id) ON DELETE CASCADE,
    line_number       INTEGER NOT NULL CHECK (line_number > 0),
    product_id        BIGINT NOT NULL REFERENCES masterdata_product(id),
    description       TEXT,
    quantity          NUMERIC(18,4) NOT NULL CHECK (quantity > 0),
    uom_id            BIGINT NOT NULL REFERENCES masterdata_uom(id),
    unit_price        NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (unit_price >= 0),
    discount_percent  NUMERIC(9,4) NOT NULL DEFAULT 0 CHECK (discount_percent BETWEEN 0 AND 100),
    discount_amount   NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
    tax_rate_id       BIGINT REFERENCES masterdata_tax_rate(id),
    tax_amount        NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
    subtotal          NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
    total             NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (total >= 0),
    UNIQUE (quotation_id, line_number)
);
